import { z } from "zod"
import { writeFile } from "node:fs/promises"
import { resolve } from "node:path"
import { defineOperation, getHost } from "@executioncontrolprotocol/plugin-sdk"
import {
  writeEditorTsconfig,
  writeGlobalCapabilityTypes,
} from "../lib/capability-types.js"

function scaffold(name: string): string {
  const label = name.replace(/\.ecp\.ts$/i, "").replace(/[-_]/g, " ")
  return `import { workflow, step, extension } from "@executioncontrolprotocol/core"

/**
 * Generated by \`ecp workflows init\`.
 * Search for capabilities with \`ecp environments search <query>\`, then replace the step below.
 * Pass JSON Schema objects to \`.accepts()\` / \`.returns()\` (do not import zod).
 */
export default workflow("${label}")
  .with([
    // Bind plugins this file needs, for example:
    // extension("@executioncontrolprotocol/jsonata"),
  ])
  .run([
    step("@executioncontrolprotocol/jsonata.transform", "Transform").with({
      expression: "$",
      data: { hello: "ecp" },
    }).as("out"),
  ])
`
}

/** `ecp workflows init`. @category CLI */
export const initOperation = defineOperation("workflows:init")
  .withInput(
    z.object({
      name: z.string().optional(),
      tsconfig: z
        .boolean()
        .optional()
        .describe(
          "Write an optional editor tsconfig.json pointing at ~/.ecp/cache/types"
        ),
    })
  )
  .withMetadata({
    summary: "Create a workflow file",
    description:
      "Write <name>.ecp.ts with a jsonata.transform step. Use ecp environments search to find capabilities. Pass --tsconfig for optional editor wiring.",
    useCases: ["Start a new workflow file"],
    examples: [
      "ecp workflows init",
      "ecp workflows init brief",
      "ecp workflows init brief --tsconfig",
    ],
    cli: { args: ["name"] },
  })
  .withHandler(async (input) => {
    const raw = input.name ? String(input.name) : "workflow"
    const fileName = raw.endsWith(".ecp.ts") ? raw : `${raw.replace(/\.ts$/i, "")}.ecp.ts`
    const path = resolve(fileName)
    await writeFile(path, scaffold(fileName), "utf8")
    const result: {
      path: string
      typesDir?: string
      tsconfig?: { path: string; status: string }
    } = { path }
    if (input.tsconfig) {
      try {
        const host = getHost()
        const written = writeGlobalCapabilityTypes({ registry: host.registry })
        result.typesDir = written.typesDir
        result.tsconfig = writeEditorTsconfig({ typesDir: written.typesDir })
      } catch {
        result.tsconfig = writeEditorTsconfig({})
      }
    }
    return result
  })
  .build()
